<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';
$user=club_require_login();$s=db()->prepare('SELECT * FROM club_posts WHERE author_user_id=? ORDER BY updated_at DESC');$s->execute([$user['id']]);$posts=$s->fetchAll();$s=db()->prepare('SELECT * FROM events WHERE author_user_id=? AND deleted_at IS NULL ORDER BY event_date DESC');$s->execute([$user['id']]);$events=$s->fetchAll();
club_member_layout_start('My posts & events');flash_render();
?>
<p>Share club news or suggest an event. A publisher reviews submissions before they appear on the website.</p>
<?php if(club_can('content.submit')||club_can('content.publish')): ?><div class="hero__actions"><a class="btn btn--primary" href="<?= e(site_url('/members/post-edit.php')) ?>">+ Write a post</a><a class="btn btn--secondary" href="<?= e(site_url('/members/event-edit.php')) ?>">+ Add an event</a></div><?php else: ?><div class="platform-panel"><p>You can submit posts and events once your membership is active.</p><a href="<?= e(site_url('/members/membership.php')) ?>">My membership</a></div><?php endif ?>
<?php foreach(['post'=>$posts,'event'=>$events] as $kind=>$rows): ?><h2><?= $kind==='post'?'My posts':'My events' ?></h2><?php if(!$rows): ?><div class="platform-panel empty-state"><p>No <?= $kind==='post'?'posts':'events' ?> yet. Your ideas are welcome.</p></div><?php endif ?><?php foreach($rows as $row): ?><article class="platform-panel"><span class="status-label"><?= e(ucfirst($row['status'])) ?></span><h3><?= e($row['title']) ?></h3><?php if($kind==='event'): ?><p><?= e(format_date($row['event_date'])) ?> · <?= $row['visibility']==='members'?'Members only':'Public' ?></p><?php endif ?><?php if($row['reviewer_note']): ?><p><strong>Reviewer feedback:</strong> <?= e($row['reviewer_note']) ?></p><?php endif ?><?php $r=db()->prepare("SELECT status,reviewer_note FROM club_revisions WHERE owner_type=? AND owner_id=? ORDER BY id DESC LIMIT 1");$r->execute([$kind,$row['id']]);$revision=$r->fetch();if($revision): ?><p>Latest revision: <strong><?= e($revision['status']) ?></strong><?= $revision['reviewer_note']?' — '.e($revision['reviewer_note']):'' ?></p><?php endif ?><?php if(club_content_editable($row)): ?><a class="btn btn--secondary" href="<?= e(site_url('/members/'.$kind.'-edit.php?id='.$row['id'])) ?>">Edit <?= $kind ?></a><?php endif ?><?php if($row['status']==='published'): ?><a class="btn btn--secondary" href="<?= e(site_url(($kind==='event'?'/event-detail.php':'/post.php').'?slug='.rawurlencode($row['slug']))) ?>">View published <?= $kind ?></a><?php endif ?></article><?php endforeach;endforeach ?>
<?php club_member_layout_end(); ?>
